/**
 * A list beside the selected item's detail (`design/archetypes/master-detail-page.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/master-detail-page.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { Component, DestroyRef, ViewEncapsulation, inject, input, output } from '@angular/core'

import {
  MEMBER_PROVIDERS,
  Ref,
  Render,
  SlotOutlet,
  SlotTemplate,
  cell,
  derived,
  elementRef,
  isTemplate,
  masterDetailFocus,
  masterDetailHolds,
  mountEffect,
  presence,
  useMember,
  watchEffect,
  watchMeasured,
} from '@polymorph/angular'
import styles from '@polymorph/recipes/archetypes/master-detail-page.module.css'
import { Button, type ButtonProps } from '../controls/Button'
import { EmptyState, type EmptyStateProps } from '../structure/EmptyState'
import { PageHeader, type PageHeaderProps } from '../structure/PageHeader'
import { SplitPane, type SplitPaneProps } from '../layout/SplitPane'

/** A list beside the selected item's detail: the inputs it takes, by the React member's prop names. */
export interface MasterDetailPageProps {
  /**
   * The way back to the list while the detail is drawn alone.
   */
  backLabel: string
  description?: string
  /**
   * The detail pane while nothing is selected, in the split. Required so the page always decides
   * it.
   */
  emptyState: EmptyStateProps
  /**
   * Names the list pane's region and the split's separator.
   */
  listLabel: string
  title: string
}

/** A list beside the selected item's detail. */
@Component({
  selector: 'pm-master-detail-page',
  encapsulation: ViewEncapsulation.None,
  host: { style: 'display: contents' },
  providers: [...MEMBER_PROVIDERS],
  imports: [Ref, Render, SlotOutlet, SlotTemplate, Button, EmptyState, PageHeader, SplitPane],
  // prettier-ignore
  template: `<ng-template pmSlot="actions" [pmSlotOf]="$"><ng-content select="[slot=actions]" /></ng-template>
<ng-template pmSlot="detail" [pmSlotOf]="$"><ng-content select="[slot=detail]" /></ng-template>
<ng-template pmSlot="list" [pmSlotOf]="$"><ng-content select="[slot=list]" /></ng-template>
<!-- root -->
<div
[attr.class]="e1()"
[attr.data-layout]="e2()"
[attr.data-pane]="e3()"
data-member="master-detail-page"
[pmRef]="root"
><pm-page-header
[title]="e4()"
[description]="e5()"
>@if (e6()) {<ng-container ngProjectAs="[slot=actions]"><ng-container [pmSlotOutlet]="'actions'" [pmSlotOf]="$" pmSlotInto="actions" /></ng-container>}</pm-page-header>
<!-- body -->
<div
[attr.class]="e7()"
[pmRef]="body"
>@if (e8()) {<!-- list -->
<section
[attr.class]="e9()"
[attr.aria-label]="e10()"
tabindex="-1"
[attr.hidden]="e11()"
data-master-detail-page-part="list"
><ng-container [pmSlotOutlet]="'list'" [pmSlotOf]="$" /></section>
@if (e12()) {<!-- detail -->
<div
[attr.class]="e13()"
data-master-detail-page-part="detail"
><!-- back -->
<div
[attr.class]="e14()"
data-master-detail-page-part="back"
><pm-button
variant="ghost"
tone="neutral"
size="sm"
icon="back"
[label]="e15()"
(click)="h1()"
></pm-button></div>
<!-- scroll -->
<div
[attr.class]="e16()"
><ng-container [pmSlotOutlet]="'detail'" [pmSlotOf]="$" /></div></div>}} @else {<pm-split-pane
[label]="e17()"
[defaultRatio]="e18()"
[startMin]="e19()"
[endMin]="e20()"
><ng-container ngProjectAs="[slot=start]"><!-- list -->
<section
[attr.class]="e21()"
[attr.aria-label]="e22()"
tabindex="-1"
data-master-detail-page-part="list"
><ng-container [pmSlotOutlet]="'list'" [pmSlotOf]="$" pmSlotInto="start" /></section></ng-container>
<ng-container ngProjectAs="[slot=end]"><!-- detail -->
<div
[attr.class]="e23()"
data-master-detail-page-part="detail"
>@if (e24()) {<!-- scroll -->
<div
[attr.class]="e25()"
><ng-container [pmSlotOutlet]="'detail'" [pmSlotOf]="$" pmSlotInto="end" /></div>} @else {<!-- empty -->
<div
[attr.class]="e26()"
><pm-empty-state
[icon]="e27()"
[title]="e28()"
[description]="e29()"
>@if (e31()) {<ng-container ngProjectAs="[slot=action]">@if (template(e30())) {<ng-container [pmRender]="e30()" />} @else {{{ e30() }}}</ng-container>}
@if (e33()) {<ng-container ngProjectAs="[slot=secondaryAction]">@if (template(e32())) {<ng-container [pmRender]="e32()" />} @else {{{ e32() }}}</ng-container>}</pm-empty-state></div>}</div></ng-container></pm-split-pane>}</div></div>`,
})
export class MasterDetailPage {
  /**
   * The way back to the list while the detail is drawn alone.
   */
  readonly backLabel = input.required<MasterDetailPageProps['backLabel']>()
  readonly description = input<MasterDetailPageProps['description']>(undefined)
  /**
   * The detail pane while nothing is selected, in the split. Required so the page always decides
   * it.
   */
  readonly emptyState = input.required<MasterDetailPageProps['emptyState']>()
  /**
   * Names the list pane's region and the split's separator.
   */
  readonly listLabel = input.required<MasterDetailPageProps['listLabel']>()
  readonly title = input.required<MasterDetailPageProps['title']>()
  /**
   * Called by the way back. The application clears its selection here.
   */
  readonly onBack = output<void>({ alias: 'back' })
  protected readonly $ = useMember({
    events: ['back'],
    props: {
      backLabel: () => this.backLabel(),
      description: () => this.description(),
      emptyState: () => this.emptyState(),
      listLabel: () => this.listLabel(),
      title: () => this.title(),
    },
  })
  protected readonly $p = this.$.props
  protected readonly narrow = cell(() => false)
  protected readonly held = cell(() => false)
  protected readonly selected = cell(() => false)
  protected readonly body = elementRef<HTMLElement>()
  protected readonly root = elementRef<HTMLElement>()
  protected readonly measure = derived(() => () => {
    if (this.root.value === null) return
    const rem = Number.parseFloat(getComputedStyle(document.documentElement).fontSize) || 16
    this.narrow.value = this.root.value.getBoundingClientRect().width < 48 * rem
  })
  protected readonly template = isTemplate
  private release1: (() => void) | undefined
  private release3: (() => void) | undefined

  constructor() {
    inject(DestroyRef).onDestroy(() => this.release1?.())
    mountEffect(() => this.effect1())
    watchMeasured(
      () => Boolean(this.$.filled('detail')),
      () => this.effect2(),
      true,
    )
    inject(DestroyRef).onDestroy(() => this.release3?.())
    mountEffect(() => this.effect3())
    watchEffect(
      () =>
        this.narrow.value
          ? this.selected.value
            ? 'detail'
            : 'list'
          : this.selected.value
            ? 'split-detail'
            : 'split',
      () => this.effect4(),
      false,
    )
  }

  protected e1() {
    return styles.page
  }

  protected e2() {
    return this.narrow.value ? 'single' : 'split'
  }

  protected e3() {
    return this.narrow.value ? (this.selected.value ? 'detail' : 'list') : undefined
  }

  protected e4(): PageHeaderProps['title'] {
    return this.$p.title
  }

  protected e5(): PageHeaderProps['description'] {
    return this.$p.description
  }

  protected e6() {
    return this.$.filled('actions')
  }

  protected e7() {
    return styles.body
  }

  protected e8() {
    return this.narrow.value
  }

  protected e9() {
    if (!this.narrow.value) return undefined as never
    return styles.list
  }

  protected e10() {
    if (!this.narrow.value) return undefined as never
    return this.$p.listLabel
  }

  protected e11() {
    if (!this.narrow.value) return undefined as never
    return presence(this.selected.value)
  }

  protected e12() {
    if (!this.narrow.value) return undefined as never
    return this.selected.value
  }

  protected e13() {
    if (!this.narrow.value) return undefined as never
    if (!this.selected.value) return undefined as never
    return styles.detail
  }

  protected e14() {
    if (!this.narrow.value) return undefined as never
    if (!this.selected.value) return undefined as never
    return styles.back
  }

  protected e15(): ButtonProps['label'] {
    if (!this.narrow.value) return undefined as never
    if (!this.selected.value) return undefined as never
    return this.$p.backLabel
  }

  protected h1(): void {
    if (!this.narrow.value) return
    if (!this.selected.value) return
    this.$.emit(this.onBack, 'onBack')
  }

  protected e16() {
    if (!this.narrow.value) return undefined as never
    if (!this.selected.value) return undefined as never
    return styles.scroll
  }

  protected e17(): SplitPaneProps['label'] {
    if (this.narrow.value) return undefined as never
    return this.$p.listLabel
  }

  protected e18(): SplitPaneProps['defaultRatio'] {
    if (this.narrow.value) return undefined as never
    return 0.32
  }

  protected e19(): SplitPaneProps['startMin'] {
    if (this.narrow.value) return undefined as never
    return 240
  }

  protected e20(): SplitPaneProps['endMin'] {
    if (this.narrow.value) return undefined as never
    return 420
  }

  protected e21() {
    if (this.narrow.value) return undefined as never
    return styles.list
  }

  protected e22() {
    if (this.narrow.value) return undefined as never
    return this.$p.listLabel
  }

  protected e23() {
    if (this.narrow.value) return undefined as never
    return styles.detail
  }

  protected e24() {
    if (this.narrow.value) return undefined as never
    return this.selected.value
  }

  protected e25() {
    if (this.narrow.value) return undefined as never
    if (!this.selected.value) return undefined as never
    return styles.scroll
  }

  protected e26() {
    if (this.narrow.value) return undefined as never
    if (this.selected.value) return undefined as never
    return styles.empty
  }

  protected e27(): EmptyStateProps['icon'] {
    if (this.narrow.value) return undefined as never
    if (this.selected.value) return undefined as never
    return this.$p.emptyState.icon
  }

  protected e28(): EmptyStateProps['title'] {
    if (this.narrow.value) return undefined as never
    if (this.selected.value) return undefined as never
    return this.$p.emptyState.title
  }

  protected e29(): EmptyStateProps['description'] {
    if (this.narrow.value) return undefined as never
    if (this.selected.value) return undefined as never
    return this.$p.emptyState.description
  }

  protected e30() {
    if (this.narrow.value) return undefined as never
    if (this.selected.value) return undefined as never
    return this.$p.emptyState.action
  }

  protected e31() {
    if (this.narrow.value) return undefined as never
    if (this.selected.value) return undefined as never
    return this.$p.emptyState.action !== undefined
  }

  protected e32() {
    if (this.narrow.value) return undefined as never
    if (this.selected.value) return undefined as never
    return this.$p.emptyState.secondaryAction
  }

  protected e33() {
    if (this.narrow.value) return undefined as never
    if (this.selected.value) return undefined as never
    return this.$p.emptyState.secondaryAction !== undefined
  }

  private effect1(): void {
    this.release1?.()
    const run = () => {
      this.measure.value()
    }
    const resize = typeof ResizeObserver === 'undefined' ? undefined : new ResizeObserver(run)
    for (const element of [this.root.value]) if (element) resize?.observe(element)
    this.release1 = () => {
      resize?.disconnect()
    }
    run()
  }

  private effect2(): void {
    this.selected.value = Boolean(this.$.filled('detail'))
  }

  private effect3(): void {
    this.release3?.()
    const listener = ($event: FocusEvent) => {
      this.held.value = masterDetailHolds(this.body.value, $event)
    }
    document.addEventListener('focusin', listener)
    this.release3 = () => document.removeEventListener('focusin', listener)
  }

  private effect4(): void {
    this.$.afterRender(() => masterDetailFocus(this.body.value, this.held.value))
  }
}
